// PLANTILLA DE RESPALDO Variado/Dinero (modo emergencia): sale en Remotion aunque la IA no logre dibujar el guion.
// emergencia.py rellena ACENTO y MOMENTOS con la palabra clave de cada escena. Si una palabra no se encuentra en la
// voz, cae en su fracción de la duración, así que esta plantilla nunca rompe el render.
import React from 'react';
import {AbsoluteFill, DUR, FONT, Fondo, Ondas, clamp, en, interpolate, useS} from './kit';

const ACENTO = '#E7FF00';
const MOMENTOS: [string, number][] = [["sueldo",1],["cuenta",1],["minuto",1]];

const momento = (i: number) => {
  try {
    return en(MOMENTOS[i][0], MOMENTOS[i][1]);
  } catch {
    return (DUR * i) / MOMENTOS.length;
  }
};
const TIEMPOS = MOMENTOS.map((_, i) => momento(i));

export const SUBS = {acento: ACENTO};
export const SFX = TIEMPOS.filter((t, i) => i === 0 || t - TIEMPOS[i - 1] >= 2).map((t) => ({t, s: 'whoosh_02'}));

const Palabra: React.FC<{texto: string; t0: number; t1: number}> = ({texto, t0, t1}) => {
  const {s, spr} = useS();
  if (s < t0 || s > t1) return null;
  const e = spr(t0, 12, 180);
  const fuera = interpolate(s, [t1 - 0.25, t1], [1, 0], clamp);
  const size = Math.min(190, 1500 / Math.max(texto.length, 1));
  return (
    <AbsoluteFill style={{alignItems: 'center', justifyContent: 'center', opacity: fuera}}>
      <div style={{fontFamily: FONT, fontWeight: 800, fontSize: size, color: ACENTO, textShadow: '0 12px 40px rgba(0,0,0,0.55)', transform: `translateY(${(1 - e) * 120}px) scale(${0.8 + 0.2 * e + (s - t0) * 0.012})`}}>{texto}</div>
    </AbsoluteFill>
  );
};

export const Escena: React.FC = () => (
  <AbsoluteFill style={{overflow: 'hidden'}}>
    <Fondo />
    {TIEMPOS.map((t, i) => (
      <Ondas key={i} x={540} y={960} t0={t} color={ACENTO} />
    ))}
    {MOMENTOS.map(([p], i) => (
      <Palabra key={i} texto={p.toUpperCase()} t0={TIEMPOS[i]} t1={i + 1 < TIEMPOS.length ? TIEMPOS[i + 1] : DUR} />
    ))}
  </AbsoluteFill>
);
